slides.solution:
secret = input()
fails = 0
while True:
    attempt = input()
    if attempt == "exit":
        break
    if fails >= 3:
        print("locked")
    elif attempt == secret:
        print("ok")
        fails = 0
    else:
        fails += 1
        print("bad")

